using System;
using System.Collections.Generic;
using System.Diagnostics;
using HarmonyLib;
using Alta.Chunks;
using Alta.Forests;
using UnityEngine;

namespace ShardPerformance
{
    /// <summary>
    /// Keeps the server from carrying forest and loose (dynamic) chunk content that no
    /// player is near. Both are the heavy parts of "the forest makes the game laggy":
    /// a forest chunk's trees/bushes are generated by a ForestGenerator, and dropped
    /// items / loose props are the chunk's dynamic content.
    ///
    /// This is a periodic server-side sweep (ShardPerformanceMod.OnUpdate calls Tick),
    /// not a Harmony patch: the game's generation is async and awaited in many places,
    /// so cancelling a call mid-flight is fragile. Instead we let the game load what it
    /// wants, then release anything with no player in it or an adjacent chunk, and let it
    /// be requested again when a player returns. Everything here is reversible: turn the
    /// setting off (or uninstall) and the game reloads normally.
    ///
    /// "Near" = the chunk a player stands in, plus its immediate neighbours
    /// (GetNeighboursForLookup). Aggressive by request: a forest chunk two chunks away
    /// holds no trees. Occupancy is read from Chunk.Players.Count (server truth), so an
    /// empty forest stays empty and a walked-into one rebuilds.
    /// </summary>
    internal static class ForestGatePatch
    {
        // Measurement only (PerfMonitor reads these): how often and how long the server
        // recomputes a player's loaded chunks. No throttling here any more.
        internal static long Calls;
        internal static long Skipped;   // retained at 0 for PerfMonitor's format
        internal static long Ticks;
        internal static double Milliseconds(long ticks) => ticks * 1000.0 / Stopwatch.Frequency;

        internal static long ForestsReleased;
        internal static long ForestsRequested;
        internal static long ItemChunksTightened;

        // A chunk is "near" if it or a neighbour holds a player. Recomputed each sweep.
        private static readonly HashSet<LocationChunk> Near = new HashSet<LocationChunk>();

        internal static string Apply(HarmonyLib.Harmony harmony)
        {
            try
            {
                harmony.Patch(
                    AccessTools.Method(typeof(PlayerChunkManager), nameof(PlayerChunkManager.LoadFromPosition)),
                    prefix: new HarmonyMethod(typeof(ForestGatePatch), nameof(TimePrefix)),
                    postfix: new HarmonyMethod(typeof(ForestGatePatch), nameof(TimePostfix)));
            }
            catch (Exception exception)
            {
                return "Chunk-timing not patched (stats only): " + exception.Message;
            }
            return "Forest/item gating ready; chunk-recompute timing patched.";
        }

        private static void TimePrefix(out long __state) => __state = Stopwatch.GetTimestamp();
        private static void TimePostfix(long __state)
        {
            Calls++;
            Ticks += Stopwatch.GetTimestamp() - __state;
        }

        /// <summary>
        /// One sweep. Cheap: a pass over loaded location chunks to find occupied ones and
        /// their neighbours, then a pass over forests releasing the far ones.
        /// </summary>
        internal static void Tick(bool forestNearOnly, bool itemsSameChunkOnly)
        {
            if (!forestNearOnly && !itemsSameChunkOnly)
                return;

            BuildNearSet();

            if (forestNearOnly)
                GateForests();

            if (itemsSameChunkOnly)
                TightenItemStreaming();
        }

        /// <summary>Every loaded location chunk that holds a player, plus its neighbours.</summary>
        private static void BuildNearSet()
        {
            Near.Clear();
            HashSet<LocationChunk> all = LocationChunk.AllLocationChunks;
            if (all == null)
                return;

            foreach (LocationChunk chunk in all)
            {
                if (chunk == null || !chunk.IsLoaded || !HasPlayer(chunk))
                    continue;
                Near.Add(chunk);
                foreach (LocationChunk neighbour in chunk.GetNeighboursForLookup())
                    if (neighbour != null)
                        Near.Add(neighbour);
            }
        }

        private static void GateForests()
        {
            IEnumerable<ForestGenerator> forests = ForestGenerator.All;
            if (forests == null)
                return;

            foreach (ForestGenerator forest in forests)
            {
                if (forest == null)
                    continue;
                // The forest belongs to the location chunk it sits in; release its dynamic
                // content for every loaded chunk that isn't near a player.
                foreach (LocationChunk chunk in ChunksOf(forest))
                {
                    if (chunk == null || !chunk.IsLoaded)
                        continue;
                    if (Near.Contains(chunk))
                        continue;
                    try
                    {
                        forest.ReleaseDynamic(chunk);
                        ForestsReleased++;
                    }
                    catch
                    {
                        // A forest that doesn't own this chunk just no-ops; ignore.
                    }
                }
            }
        }

        /// <summary>
        /// Loose/dynamic content only reaches a player for the chunk they stand in. Done by
        /// forcing each far chunk's dynamic load strength off; near chunks keep theirs. We
        /// only touch chunks we changed, and restore them when a player comes back, so an
        /// empty server returns to vanilla behaviour.
        /// </summary>
        private static readonly HashSet<LocationChunk> Tightened = new HashSet<LocationChunk>();

        private static void TightenItemStreaming()
        {
            HashSet<LocationChunk> all = LocationChunk.AllLocationChunks;
            if (all == null)
                return;

            foreach (LocationChunk chunk in all)
            {
                if (chunk == null || !chunk.IsLoaded)
                    continue;

                // Same-chunk only: a chunk streams loose content when it itself holds a
                // player. Neighbours (which Near includes) do not, by request.
                bool wanted = HasPlayer(chunk);
                if (!wanted && !Tightened.Contains(chunk))
                {
                    chunk.SetOverrideLoadDistance(0f, true);
                    Tightened.Add(chunk);
                    ItemChunksTightened++;
                }
                else if (wanted && Tightened.Remove(chunk))
                {
                    // Give the chunk its normal distance back.
                    chunk.SetOverrideLoadDistance(0f, false);
                }
            }
        }

        private static bool HasPlayer(Chunk chunk)
        {
            ChunkPlayerManager players = chunk.Players;
            return players != null && players.Count > 0;
        }

        /// <summary>
        /// The location chunks a forest covers. A ForestGenerator is a NetworkEntityBehaviour
        /// sitting in one location chunk; its content chunks are that chunk and the ones it
        /// declares. We derive them from the chunk the forest is in.
        /// </summary>
        private static IEnumerable<LocationChunk> ChunksOf(ForestGenerator forest)
        {
            LocationChunk home = LocationChunkHelper.GetBestContaining(forest.transform.position, null);
            if (home != null)
            {
                yield return home;
                foreach (LocationChunk neighbour in home.GetNeighboursForLookup())
                    if (neighbour != null)
                        yield return neighbour;
            }
        }
    }
}
